    pub fn handle_trades(&mut self, mut client: Value, mut message: Value) {
        let __message_empty = indexmap::IndexMap::new();
        let message = message.as_map().unwrap_or(&__message_empty);
        //
        //     {
        //         "arg": { channel: "trades", instId: "BTC-USDT" },
        //         "data": [
        //             {
        //                 "instId": "BTC-USDT",
        //                 "tradeId": "216970876",
        //                 "px": "31684.5",
        //                 "sz": "0.00001186",
        //                 "side": "buy",
        //                 "ts": "1626531038288"
        //             }
        //         ]
        //     }
        //     {
        //         "arg": {
        //             "channel": "trades-all",
        //             "instId": "BTC-USDT"
        //         },
        //         "data": [
        //             {
        //                 "instId": "BTC-USDT",
        //                 "tradeId": "130639474",
        //                 "px": "42219.9",
        //                 "sz": "0.12060306",
        //                 "side": "buy",
        //                 "source": "0",
        //                 "ts": "1630048897897"
        //             }
        //         ]
        //     }
        //
        let mut arg: crate::value::Dict = message.get("arg").cloned().unwrap_or_default().into_dict();
        let mut channel: Option<String> = self.safe_string_k(&arg, "channel", &[]).as_str().map(str::to_owned);
        let mut marketId: Option<String> = self.safe_string_k(&arg, "instId", &[]).as_str().map(str::to_owned);
        let mut symbol: Option<String> = self.safe_symbol(marketId.map(Value::from).unwrap_or(Value::Null), None, &[]).as_str().map(str::to_owned);
        let mut data: crate::value::List = message.get("data").cloned().unwrap_or_default().into_list();
        let mut tradesLimit: i64 = self.safe_integer_k(self.options.clone(), "tradesLimit", &[Value::Int(1000)]).as_i64().unwrap_or(1000);
        {
                        let mut i: i64 = 0;
            let mut __for_first_528: bool = true;
            while { if !__for_first_528 { i += 1; } __for_first_528 = false; i < (data.len() as i64) } {
            let mut trade: crate::value::Dict = self.parse_trade(data.get(i as usize).cloned().unwrap_or(Value::Null), None).into_dict();
            let mut stored: Option<crate::pro::cache::Cache> = self.trades.lookup(&symbol);
            if (stored.is_none()) {
                stored = Some(ArrayCache::new(Value::from(tradesLimit)));
                CacheStore::put(&mut self.trades, &symbol, stored.clone());
            }
            stored.append(Value::Dict(trade));
            if (channel.is_some()) {
                let mut messageHash: String = format!("{}{}", Value::Str(format!("{}{}", channel.as_deref().unwrap_or("null"), ":").into()), symbol.as_deref().unwrap_or("null"));
                client.resolve(Value::from(&stored), messageHash.as_str());
            }
        }
        }
}

